# Enem 2015, 2º dia, caderno azul: Matemática (questões 136 a 180 do caderno; no site, 1 a 45, com numeroOriginal).
# Texto dos blocos do PDF quando limpo; fórmulas, tabelas e listas reescritas à mão a partir das páginas. Gabarito oficial do Inep (caderno azul).
import sys, pathlib, re
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1] / "tools"))
from aj import completar
from enem_aj import carregar_enem

ID = "enem-2015-matematica"
META = {"id": ID, "banca": "Enem", "ano": 2015, "titulo": "Enem 2015: Matemática", "fonte": "Inep", "dataExame": "2015-10-25",
        "duracaoMinutos": 150, "area": "Matemática", "caderno": "azul", "dia": 2}
R = {n: {"numero": n, "enunciado": "", "alternativas": {}} for n in range(1, 46)}
D = carregar_enem("enem-2015-dia2-azul")
T = lambda n, i: D[n]["paragrafos"][i][1]
fonte = lambda n, i: f'<p class="fonte">{T(n, i)}</p>'
ap = lambda *xs: "".join(f'<p class="apoio">{x}</p>' for x in xs)
p = lambda *xs: "".join(f"<p>{x}</p>" for x in xs)
K = lambda s: f"\\({s}\\)"


def tab(cab, linhas):
    return "<table><thead><tr>" + "".join(f"<th>{c}</th>" for c in cab) + "</tr></thead><tbody>" + "".join("<tr>" + "".join(f"<td>{c}</td>" for c in l) + "</tr>" for l in linhas) + "</tbody></table>"


def figs(*pares):
    return [{"arquivo": a, "alt": t} for a, t in pares]


Q = {}


def X(n, assunto, expl, enun, imagens=(), tags=(), alts=None):
    Q[n - 135] = {"materia": "Matemática", "assunto": assunto, "area": "Matemática", "tags": list(tags), "numeroOriginal": n,
                  "enunciado": enun, "alternativas": dict(alts or D[n]["alternativas"]), "imagens": list(imagens), "explicacao": expl}


X(136, "Funções", "<p>Leia o gráfico da esquerda para a direita, aplicando as regras uma de cada vez:</p><p>1) entre 10 h e 11 h, o valor passa de V<sub>i</sub>: vende metade; 2) perto das 12 h, cai abaixo de V<sub>m</sub>: compra a mesma quantidade que tem; 3) perto das 13 h, passa de novo de V<sub>i</sub>: vende metade; 4) entre 13 h e 14 h, passa de V<sub>o</sub>: vende tudo.</p><p>Depois disso ele não tem mais ações: o valor volta a passar de V<sub>i</sub> perto das 15 h, mas não há o que vender, e a regra II mandaria comprar “a mesma quantidade de ações que possui”, que agora é zero. Total: <strong>4 operações</strong>. Alternativa <strong>B</strong>.</p>",
  p("Um investidor inicia um dia com <em>x</em> ações de uma empresa. No decorrer desse dia, ele efetua apenas dois tipos de operações, comprar ou vender ações. Para realizar essas operações, ele segue estes critérios:")
  + ap("I. vende metade das ações que possui, assim que seu valor fica acima do valor ideal (<em>Vi</em>);", "II. compra a mesma quantidade de ações que possui, assim que seu valor fica abaixo do valor mínimo (<em>Vm</em>);", "III. vende todas as ações que possui, quando seu valor fica acima do valor ótimo (<em>Vo</em>).")
  + p("O gráfico apresenta o período de operações e a variação do valor de cada ação, em reais, no decorrer daquele dia e a indicação dos valores ideal, mínimo e ótimo.") + "[[fig:1]]" + p("Quantas operações o investidor fez naquele dia?"),
  figs(("q136", "Gráfico do valor da ação (R$) × tempo (das 10 h às 17 h), com três linhas horizontais: Vo (alta), Vi (média) e Vm (baixa). O valor começa entre Vm e Vi, sobe acima de Vi perto das 11 h, cai abaixo de Vm perto das 12 h, sobe até passar de Vo perto das 14 h, depois desce abaixo de Vi e oscila entre Vm e Vi até as 17 h.")), ["leitura de gráfico"])
X(137, "Geometria plana", "<p>O tampo circular precisa cobrir o triângulo equilátero de lado 30 cm: o menor círculo que faz isso é o <strong>circunscrito</strong>, de raio R = lado/√3 = 30/1,7 ≈ 17,6 cm. Entre os tampos disponíveis, o menor com raio maior ou igual a isso é o de <strong>18 cm</strong>. Alternativa <strong>A</strong>.</p><p>Quem usa o raio do círculo inscrito (cerca de 8,8 cm) acha que qualquer tampo serve; quem confunde raio com lado escolhe 30 cm (C).</p>",
  p(T(137, 0), T(137, 1), "Considere 1,7 como aproximação para \\(\\sqrt{3}\\).", T(137, 3)), tags=["triângulo equilátero", "circunferência circunscrita"])
X(138, "Funções", "<p>Q ≤ P onde a curva de Q está abaixo ou encosta na reta de P: de 0 até o primeiro cruzamento, perto de 20 km, e depois do segundo cruzamento, em 100 km, até 160 km. Alternativa <strong>D</strong>.</p><p>Entre 20 e 100 km, a curva de Q fica acima da reta de P (A, B e E incluem esse trecho).</p>",
  p("Atualmente existem diversas locadoras de veículos, permitindo uma concorrência saudável para o mercado, fazendo com que os preços se tornem acessíveis.", "Nas locadoras P e Q, o valor da diária de seus carros depende da distância percorrida, conforme o gráfico.") + "[[fig:1]]"
  + p("O valor pago na locadora Q é menor ou igual àquele pago na locadora P para distâncias, em quilômetros, presentes em qual(is) intervalo(s)?"),
  figs(("q138", "Gráfico do valor da diária (R$) × distância percorrida (km, de 0 a 160). P é uma reta crescente que começa perto de R$ 60 e vai a R$ 160. Q é uma curva que começa em R$ 40, sobe depressa, cruza P perto de 20 km, fica acima dela até 100 km, cruza de novo e termina perto de R$ 140 em 160 km.")), ["leitura de gráfico"])
X(139, "Frações e porcentagem", "<p>A carta da mesa vale 6/8 = 3/4 = 0,75. Na mão, valem o mesmo: <strong>75%</strong>, <strong>0,75</strong> e a <strong>figura</strong> com 3/4 da área pintada. São 3 cartas. Alternativa <strong>E</strong>.</p><p>Cuidado com as pegadinhas: 3,4, 34%, 4,3, 7,5, 4/3 e 6,8 usam os mesmos algarismos, mas não valem 3/4.</p>",
  p(T(139, 0)) + "[[fig:1]]" + p(T(139, 2)),
  figs(("q139", "Carta da mesa: a fração 6/8 e um quadrado dividido em 8 triângulos, 6 pintados. Cartas da mão, em leque: 75%, 3,4, 34%, 0,75, 4,3, 7,5, 4/3, 6,8 e uma carta com um losango dividido em quatro partes, três delas pintadas.")), ["frações equivalentes"])
X(140, "Estatística", "<p>Para as classes A/B, a maior participação é a da <strong>internet</strong> (40%). Para as classes C/D, a maior é a dos <strong>Correios</strong> (33%). Alternativa <strong>B</strong>.</p><p>A inverte a ordem; as outras escolhem categorias com percentuais menores.</p>",
  p(T(140, 0).replace("site", "<em>site</em>")) + "[[fig:1]]" + p(T(140, 2), T(140, 3)),
  figs(("q140", "Gráfico de barras “Participação em promoções do tipo sorteio ou concurso em uma região”, em %. Classes A/B: Correios 34, Internet 40, Mídias sociais 37, SMS 35, Rádio/TV 28. Classes C/D: Correios 33, Internet 24, Mídias sociais 20, SMS 30, Rádio/TV 28.")), ["leitura de gráfico"])
X(141, "Geometria espacial", "<p>Volume da embalagem: 20 × 10 × 10 = 2 000 cm³. O chocolate (1 000 cm³) cresce 25% e ocupa 1 250 cm³; sobram 750 cm³ para o sorvete de morango <em>já cremoso</em>. Como a mistura também cresce 25%, o volume líquido é V × 1,25 = 750, logo V = <strong>600 cm³</strong>. Alternativa <strong>C</strong>.</p><p>750 cm³ (D) esquece que o morango também aumenta de volume.</p>",
  p("Uma fábrica de sorvetes utiliza embalagens plásticas no formato de paralelepípedo retangular reto. Internamente, a embalagem tem 10 cm de altura e base de 20 cm por 10 cm. No processo de confecção do sorvete, uma mistura é colocada na embalagem no estado líquido e, quando levada ao congelador, tem seu volume aumentado em 25%, ficando com consistência cremosa.",
    "Inicialmente é colocada na embalagem uma mistura sabor chocolate com volume de 1 000 cm<sup>3</sup> e, após essa mistura ficar cremosa, será adicionada uma mistura sabor morango, de modo que, ao final do processo de congelamento, a embalagem fique completamente preenchida com sorvete, sem transbordar.",
    "O volume máximo, em cm<sup>3</sup>, da mistura sabor morango que deverá ser colocado na embalagem é"), tags=["volume", "porcentagem"])
X(142, "Probabilidade", "<p>Há 20 senhas favoráveis (1 a 20) em 100 possíveis: 20/100. Alternativa <strong>C</strong>.</p><p>19/100 (B) esquece de contar uma das pontas.</p>",
  p("Em uma central de atendimento, cem pessoas receberam senhas numeradas de 1 até 100. Uma das senhas é sorteada ao acaso.", "Qual é a probabilidade de a senha sorteada ser um número de 1 a 20?"),
  alts={k: K(f"\\dfrac{{{v}}}{{100}}") for k, v in zip("ABCDE", [1, 19, 20, 21, 80])})
X(143, "Estatística", "<p>Ordenando os 8 tempos: 20,50; 20,60; 20,60; 20,80; 20,90; 20,90; 20,90; 20,96. Com quantidade par, a mediana é a média dos dois centrais: (20,80 + 20,90) ÷ 2 = <strong>20,85</strong>. Alternativa <strong>D</strong>.</p><p>20,90 (E) é a moda.</p>",
  p("Em uma seletiva para a final dos 100 metros livres de natação, numa olimpíada, os atletas, em suas respectivas raias, obtiveram os seguintes tempos:")
  + tab(["Raia", "Tempo (segundo)"], [[str(i), t] for i, t in enumerate(["20,90", "20,90", "20,50", "20,80", "20,60", "20,60", "20,90", "20,96"], 1)]) + p("A mediana dos tempos apresentados no quadro é"), tags=["mediana"])
X(144, "Geometria plana", "<p>Antes: trapézio de bases 600 cm e 360 cm e altura 580 cm: (600 + 360) ÷ 2 × 580 = 278 400 cm². Depois: retângulo 490 × 580 = 284 200 cm². Diferença: <strong>aumento de 5 800 cm²</strong>. Alternativa <strong>A</strong>.</p>",
  p("O Esquema I mostra a configuração de uma quadra de basquete. Os trapézios em cinza, chamados de garrafões, correspondem a áreas restritivas.") + "[[fig:1]]"
  + p("Visando atender as orientações do Comitê Central da Federação Internacional de Basquete (Fiba) em 2010, que unificou as marcações das diversas ligas, foi prevista uma modificação nos garrafões das quadras, que passariam a ser retângulos, como mostra o Esquema II.") + "[[fig:2]]"
  + p("Após executadas as modificações previstas, houve uma alteração na área ocupada por cada garrafão, que corresponde a um(a)"),
  figs(("q144a", "Esquema I: quadra com garrafões em forma de trapézio, com base de 600 cm junto à linha de fundo, base de 360 cm do outro lado e comprimento de 580 cm."),
       ("q144b", "Esquema II: quadra com garrafões retangulares de 490 cm de largura por 580 cm de comprimento.")), ["área do trapézio"],
  alts={k: v.replace("cm²", "cm<sup>2</sup>") for k, v in D[144]["alternativas"].items()})
X(145, "Operações e problemas", "<p>Cada escola recebe o mesmo número de ingressos, de uma sessão só, sem sobras: esse número precisa dividir 400 e 320. Para ter o <strong>mínimo</strong> de escolas, cada uma recebe o máximo possível: MDC(400, 320) = 80. Escolas: 400 ÷ 80 + 320 ÷ 80 = 5 + 4 = <strong>9</strong>. Alternativa <strong>C</strong>.</p><p>2 escolas (A) dariam quantidades diferentes por escola.</p>",
  p(T(145, 0)) + ap(T(145, 1), T(145, 2), T(145, 3)) + p(T(145, 4)), tags=["MDC"])
X(146, "Geometria espacial", "<p>Cisterna atual: raio 1 m, altura 3 m: V = 3 · 1² · 3 = 9 m³. Nova, com a mesma altura: 81 = 3 · r² · 3, logo r² = 9 e r = 3 m. Aumento: 3 − 1 = <strong>2 m</strong>. Alternativa <strong>C</strong>.</p><p>8 m (E) é o aumento do volume dividido de forma errada; 3,5 m (D) confunde raio com diâmetro.</p>",
  p("Para resolver o problema de abastecimento de água foi decidida, numa reunião do condomínio, a construção de uma nova cisterna. A cisterna atual tem formato cilíndrico, com 3 m de altura e 2 m de diâmetro, e estimou-se que a nova cisterna deverá comportar 81 m<sup>3</sup> de água, mantendo o formato cilíndrico e a altura da atual. Após a inauguração da nova cisterna a antiga será desativada. Utilize 3,0 como aproximação para π.",
    "Qual deve ser o aumento, em metros, no raio da cisterna para atingir o volume desejado?"), tags=["cilindro", "volume"])
X(147, "Análise combinatória", "<p>Falta a nota do jurado B em Bateria para as cinco escolas (cada uma de 6 a 10: 5 opções). A escola II tem 66 + x e a IV, 68 + y; I, III e V não alcançam a II em nenhum caso. A II vence se 66 + x > 68 + y, ou se empatar, pois ganha no desempate (Enredo e Harmonia: 20 contra 19). Então x − y ≥ 2.</p><p>Pares (x, y): (8, 6), (9, 6), (9, 7), (10, 6), (10, 7), (10, 8): 6 pares. As outras três escolas podem ter qualquer nota: 5³ = 125. Total: 6 × 125 = <strong>750</strong>. Alternativa <strong>C</strong>.</p><p>Esquecer as notas das outras escolas dá 6; esquecer o desempate dá 3 × 125 = 375.</p>",
  p(T(147, 0)) + "[[fig:1]]" + p(T(147, 17)),
  figs(("q147", "Tabela das notas dos jurados A e B nos quesitos 1. Fantasia e Alegoria, 2. Evolução e Conjunto, 3. Enredo e Harmonia e 4. Bateria (só a nota A divulgada), com o total parcial. Escola I: 6, 7; 8, 8; 9, 9; 8 — total 55. Escola II: 9, 8; 10, 9; 10, 10; 10 — total 66. Escola III: 8, 8; 7, 8; 6, 7; 6 — total 50. Escola IV: 9, 10; 10, 10; 9, 10; 10 — total 68. Escola V: 8, 7; 9, 8; 6, 8; 8 — total 54.")), ["princípio multiplicativo"])
X(148, "Geometria espacial", "<p>A área de 10 m × 32 m comporta, em cada camada, 32 ÷ 6,4 = 5 contêineres num sentido e 10 ÷ 2,5 = 4 no outro: 20 por camada, sem sobras. Para 100 contêineres, 100 ÷ 20 = 5 camadas, e a altura é 5 × 2,5 = <strong>12,5 m</strong>. Alternativa <strong>A</strong>.</p>",
  p(T(148, 0)) + "[[fig:1]][[fig:2]]" + p("De acordo com as normas desse porto, os contêineres deverão ser empilhados de forma a não sobrarem espaços nem ultrapassarem a área delimitada.", "Após o empilhamento total da carga e atendendo à norma do porto, a altura mínima a ser atingida por essa pilha de contêineres é"),
  figs(("q148a", "Figura 1: contêiner em forma de paralelepípedo, com 6,4 m de comprimento, 2,5 m de largura e 2,5 m de altura."), ("q148b", "Figura 2: retângulo de 10 m por 32 m, a área para armazenar os contêineres.")), ["volume", "divisão"])
X(149, "Geometria espacial", "<p>O cubo tem 6 faces e 8 vértices. Cortando cada canto, cada face vira um octógono (continuam 6 faces) e cada vértice dá lugar a uma face triangular nova (8 faces). Total: 6 + 8 = <strong>14</strong> faces, logo 14 cores. Alternativa <strong>C</strong>.</p>",
  p(T(149, 0), T(149, 1)), tags=["poliedros"])
X(150, "Funções", "<p>A arrecadação é p · q = p(400 − 100p) e deve continuar R$ 300,00: 400p − 100p² = 300, ou p² − 4p + 3 = 0, com raízes p = 1 e p = 3. O preço atual é R$ 3,00 (300 ÷ 100). Para vender o máximo, o novo preço é <strong>R$ 1,00</strong>, que está entre R$ 0,50 e R$ 1,50. Alternativa <strong>A</strong>.</p>",
  p("Uma padaria vende, em média, 100 pães especiais por dia e arrecada com essas vendas, em média, R$ 300,00. Constatou-se que a quantidade de pães especiais vendidos diariamente aumenta, caso o preço seja reduzido, de acordo com a equação") + ap(K("q = 400 - 100p,"))
  + p("na qual <em>q</em> representa a quantidade de pães especiais vendidos diariamente e <em>p</em>, o seu preço em reais.", "A fim de aumentar o fluxo de clientes, o gerente da padaria decidiu fazer uma promoção. Para tanto, modificará o preço do pão especial de modo que a quantidade a ser vendida diariamente seja a maior possível, sem diminuir a média de arrecadação diária na venda desse produto.", "O preço <em>p</em>, em reais, do pão especial nessa promoção deverá estar no intervalo"),
  tags=["equação do 2º grau"], alts={k: f"R$ {a} ≤ <em>p</em> &lt; R$ {b}" for k, (a, b) in zip("ABCDE", [("0,50", "1,50"), ("1,50", "2,50"), ("2,50", "3,50"), ("3,50", "4,50"), ("4,50", "5,50")])})
X(151, "Probabilidade", "<p>Uma menina desenvolve a doença se não estiver protegida: não vacinada, ou vacinada sem a vacina funcionar. Com fração x vacinada: P = 0,5 · (1 − 0,98x). Queremos P ≤ 0,059: 1 − 0,98x ≤ 0,118, logo 0,98x ≥ 0,882 e x ≥ 0,9. A menor cobertura que atende é <strong>90%</strong>, a proposta I. Alternativa <strong>A</strong>.</p><p>As propostas III e V também atingiriam a meta, mas vacinam mais pessoas; II e IV não atingem.</p>",
  p(T(151, 0)) + ap(*[T(151, i) for i in range(1, 6)]) + p(T(151, 6)) + fonte(151, 7) + p(T(151, 8)), tags=["probabilidade condicional", "porcentagem"])
X(152, "Funções", "<p>Crescimento de 50% ao ano é multiplicar por 1,5 a cada ano. No ano 1 são 8 000; no ano t, 8 000 · 1,5<sup>t−1</sup>. Alternativa <strong>E</strong>.</p><p>D usaria 0,5, que é uma queda pela metade.</p>",
  p(T(152, 0).replace(" P ", " <em>P</em> ").replace(" t ", " <em>t</em> "), "Se a estimativa for alcançada, qual é a expressão que determina o número de unidades produzidas <em>P</em> em função de <em>t</em>, para <em>t</em> ≥ 1?"),
  tags=["função exponencial"],
  alts={"A": K("P(t) = 0{,}5 \\cdot t^{-1} + 8\\,000"), "B": K("P(t) = 50 \\cdot t^{-1} + 8\\,000"), "C": K("P(t) = 4\\,000 \\cdot t^{-1} + 8\\,000"), "D": K("P(t) = 8\\,000 \\cdot (0{,}5)^{t-1}"), "E": K("P(t) = 8\\,000 \\cdot (1{,}5)^{t-1}")})
X(153, "Geometria plana", "<p>As áreas precisam estar na proporção 60% : 10% : 30%, isto é, 6 : 1 : 3. O pentágono regular, ligando o centro aos vértices, fica dividido em 5 triângulos iguais (20% cada). No desenho, carboidratos ocupam 3 triângulos (60%), gorduras 1 triângulo e meio (30%) e proteínas meio triângulo (10%), cortado pelo ponto médio do lado. Alternativa <strong>C</strong>.</p><p>Nos outros polígonos, as divisões desenhadas não dão essas proporções.</p>",
  p(T(153, 0)) + "[[fig:1]]" + p(T(153, 2)),
  figs(("q153", "Cinco polígonos regulares divididos em regiões de carboidratos, gorduras e proteínas: um triângulo equilátero com faixas horizontais, um losango, um pentágono, um hexágono e um octógono, todos com regiões que partem do centro e marcas indicando segmentos iguais.")), ["áreas", "proporção"])
X(154, "Logaritmos", "<p>Se o eixo x divide a altura ao meio, as pontas da curva têm y = −h/2 e y = h/2, isto é, x₁ = 10<sup>−h/2</sup> e x₂ = 10<sup>h/2</sup>, com x₂ − x₁ = n. Chamando u = 10<sup>h/2</sup>: u − 1/u = n, ou u² − nu − 1 = 0, cuja raiz positiva é u = (n + √(n² + 4))/2. Então h = 2 log u. Alternativa <strong>E</strong>.</p><p>D esquece o fator 2 (daria só metade da altura).</p>",
  p("Um engenheiro projetou um automóvel cujos vidros das portas dianteiras foram desenhados de forma que as suas bordas superiores fossem representadas pela curva de equação y = log (x), conforme a figura.") + "[[fig:1]]"
  + p("A forma do vidro foi concebida de modo que o eixo <em>x</em> sempre divida ao meio a altura <em>h</em> do vidro e a base do vidro seja paralela ao eixo <em>x</em>. Obedecendo a essas condições, o engenheiro determinou uma expressão que fornece a altura <em>h</em> do vidro em função da medida <em>n</em> de sua base, em metros.", "A expressão algébrica que determina a altura do vidro é"),
  figs(("q154", "Gráfico de y = log(x): a região do vidro, sombreada, fica entre a curva, uma reta vertical à direita e a base horizontal embaixo. A curva passa pelo ponto (1, 0); a altura total h é dividida ao meio pelo eixo x, e a base mede n.")), ["função logarítmica"],
  alts={"A": K("\\log\\left(\\dfrac{n + \\sqrt{n^2+4}}{2}\\right) - \\log\\left(\\dfrac{n - \\sqrt{n^2+4}}{2}\\right)"), "B": K("\\log\\left(1 + \\dfrac{n}{2}\\right) - \\log\\left(1 - \\dfrac{n}{2}\\right)"),
        "C": K("\\log\\left(1 + \\dfrac{n}{2}\\right) + \\log\\left(1 - \\dfrac{n}{2}\\right)"), "D": K("\\log\\left(\\dfrac{n + \\sqrt{n^2+4}}{2}\\right)"), "E": K("2\\log\\left(\\dfrac{n + \\sqrt{n^2+4}}{2}\\right)")})
X(155, "Geometria plana", "<p>As duas antenas antigas têm círculos de raio 2 km, tangentes em O: juntas cobrem 2 · π · 2² = 8π. A nova circunferência, com centro em O, tangencia as duas por fora do conjunto; seu raio é o diâmetro de uma delas: 4 km. Área nova: π · 4² = 16π. A área foi <strong>ampliada em 8π</strong>. Alternativa <strong>A</strong>.</p><p>16π (C) é a área total nova, não o aumento.</p>",
  p("Uma empresa de telefonia celular possui duas antenas que serão substituídas por uma nova, mais potente. As áreas de cobertura das antenas que serão substituídas são círculos de raio 2 km, cujas circunferências se tangenciam no ponto <em>O</em>, como mostra a figura.") + "[[fig:1]]"
  + p("O ponto <em>O</em> indica a posição da nova antena, e sua região de cobertura será um círculo cuja circunferência tangenciará externamente as circunferências das áreas de cobertura menores.", "Com a instalação da nova antena, a medida da área de cobertura, em quilômetros quadrados, foi ampliada em"),
  figs(("q155", "Dois círculos iguais, “Área de cobertura Antena 1” e “Antena 2”, tangentes no ponto O, dentro de um círculo maior, “Área de cobertura Nova antena”, com centro em O, que toca os dois por fora.")), ["área do círculo"])
X(156, "Matemática financeira", "<p>Antes da décima prestação, nove já foram pagas e o saldo caiu 9 × 500 = 4 500: restam 175 500. A décima prestação é 500 + 1% de 175 500 = 500 + 1 755 = <strong>R$ 2.255,00</strong>. Alternativa <strong>D</strong>.</p><p>Usar o saldo depois de 10 amortizações dá 2.250; usar o saldo inicial dá 2.300 (E).</p>",
  p(T(156, 0), T(156, 1)), tags=["sistema de amortização constante"])
X(157, "Notação científica", "<p>4,129 milhões de toneladas = 4,129 × 10⁶ t, e cada tonelada tem 10³ kg: 4,129 × 10⁹ kg. Alternativa <strong>C</strong>.</p><p>4,129 × 10⁶ (B) para em toneladas.</p>",
  p(T(157, 0)) + fonte(157, 1) + p(T(157, 2)), alts={k: v.replace("× 10", "× 10<sup>").replace("<sup>3", "<sup>3</sup>").replace("<sup>6", "<sup>6</sup>").replace("<sup>9", "<sup>9</sup>").replace("<sup>12", "<sup>12</sup>").replace("<sup>15", "<sup>15</sup>") for k, v in D[157]["alternativas"].items()})
X(158, "Razão e proporção", "<p>Pela dose de Y: 14 = 42 · i/(i + 12), logo 14i + 168 = 42i e i = 6 anos. Dose de X: 60 · 6/(6 + 12) = 60 · 1/3 = <strong>20 mg</strong>. Alternativa <strong>B</strong>.</p>",
  p("A expressão “Fórmula de Young” é utilizada para calcular a dose infantil de um medicamento, dada a dose do adulto:") + ap(K("\\text{dose de criança} = \\left(\\dfrac{\\text{idade da criança (em anos)}}{\\text{idade da criança (em anos)} + 12}\\right) \\cdot \\text{dose do adulto}"))
  + p("Uma enfermeira deve administrar um medicamento X a uma criança inconsciente, cuja dosagem de adulto é de 60 mg. A enfermeira não consegue descobrir onde está registrada a idade da criança no prontuário, mas identifica que, algumas horas antes, foi administrada a ela uma dose de 14 mg de um medicamento Y, cuja dosagem de adulto é 42 mg. Sabe-se que a dose da medicação Y administrada à criança estava correta.", "Então, a enfermeira deverá ministrar uma dosagem do medicamento X, em miligramas, igual a"), tags=["fórmula"])
X(159, "Estatística", "<p>Cada faixa de 10% tem 10,18 milhões de pessoas, e a renda total é 101,8 milhões × 1 202. Média dos 10% mais ricos: 44,5% da renda total ÷ 10% das pessoas = 4,45 × 1 202 = 5 348,90. Média dos 10% mais pobres: 0,11 × 1 202 = 132,22. Diferença: <strong>R$ 5.216,68</strong>. Alternativa <strong>E</strong>.</p>",
  p(T(159, 0)) + fonte(159, 1) + p(T(159, 2)), tags=["média", "porcentagem"])
X(160, "Razão e proporção", "<p>Na foto, a caneta mede 1,4 cm, mas na realidade 16,8 cm: escala de 16,8 ÷ 1,4 = 12. Largura real: 2,2 × 12 = 26,4 cm; comprimento real: 3,4 × 12 = 40,8 cm. Alternativa <strong>D</strong>.</p>",
  p(T(160, 0).replace("(c)", "(<em>c</em>)").replace("(L)", "(<em>L</em>)").replace("(C)", "(<em>C</em>)")) + "[[fig:1]]" + p(T(160, -1)),
  figs(("q160", "Fotografia de uma pegada no chão, com uma caneta ao lado. Medidas na foto: caneta c = 1,4 cm; largura da pegada L = 2,2 cm; comprimento C = 3,4 cm.")), ["escala"])
X(161, "Geometria plana", "<p>A malha se repete em quadrados de lado d mm. Em cada um, a parte livre é um quadrado de lado (d − 1). A taxa de cobertura de 75% deixa 25% livres: (d − 1)²/d² = 1/4, logo (d − 1)/d = 1/2 e <strong>d = 2 mm</strong>. Alternativa <strong>A</strong>.</p>",
  p(T(161, 0).replace("(d − 1)", "(<em>d</em> − 1)").replace("(d – 1)", "(<em>d</em> − 1)")) + "[[fig:1]]" + p(*[x for t, x in D[161]["paragrafos"][1:] if t == "p"]),
  figs(("q161", "Malha de fitas pretas de 1 mm de largura, cruzadas na vertical e na horizontal, deixando quadrados brancos; a distância entre o início de uma fita e o da seguinte é d.")), ["área", "porcentagem"],
  alts={"A": "2", "B": "1", "C": K("\\dfrac{11}{3}"), "D": K("\\dfrac{4}{3}"), "E": K("\\dfrac{2}{3}")})
X(162, "Operações e problemas", "<p>As peças devem ter o mesmo comprimento, dividir 540, 810 e 1 080 sem sobras e ser as maiores possíveis abaixo de 2 m. MDC(540, 810, 1 080) = 270 cm, que passa de 200 cm; o próximo divisor comum menor é 270 ÷ 2 = 135 cm. Peças: 40 × 4 + 30 × 6 + 10 × 8 = 160 + 180 + 80 = <strong>420</strong>. Alternativa <strong>E</strong>.</p><p>Usar 270 cm daria 210 peças (C), mas descumpre o limite de 2 m.</p>",
  p(T(162, 0), T(162, 1)), tags=["MDC"])
X(163, "Operações e problemas", "<p>3 mL = 300 unidades (cada unidade é 0,01 mL). Cada aplicação gasta 10 unidades mais 2 descartadas: 12. Aplicações por refil: 300 ÷ 12 = <strong>25</strong>. Alternativa <strong>A</strong>.</p><p>Ignorar o descarte dá 30; contar as duas doses diárias como uma aplicação só leva a 12 ou 13.</p>",
  p("A insulina é utilizada no tratamento de pacientes com diabetes para o controle glicêmico. Para facilitar sua aplicação, foi desenvolvida uma “caneta” na qual pode ser inserido um refil contendo 3 mL de insulina, como mostra a imagem.") + "[[fig:1]]"
  + p("Para controle das aplicações, definiu-se a unidade de insulina como 0,01 mL. Antes de cada aplicação, é necessário descartar 2 unidades de insulina, de forma a retirar possíveis bolhas de ar.", "A um paciente foram prescritas duas aplicações diárias: 10 unidades de insulina pela manhã e 10 à noite.", "Qual o número máximo de aplicações por refil que o paciente poderá utilizar com a dosagem prescrita?"),
  figs(("q163", "Fotografia de uma caneta de insulina com a tampa retirada.")), ["unidades de medida"])
X(164, "Análise combinatória", "<p>No mapa, há 9 poltronas livres para 7 pessoas: o número de formas de ocupá-las é o arranjo A(9, 7) = 9!/(9 − 7)! = 9!/2!. Alternativa <strong>A</strong>.</p><p>B é a combinação (escolhe as poltronas, mas não quem senta em cada uma).</p>",
  p(T(164, 0).replace("site", "<em>site</em>")) + "[[fig:1]]" + p("O número de formas distintas de se acomodar a família nesse voo é calculado por"),
  figs(("q164", "Mapa de poltronas de um avião: quase todas marcadas com X (ocupadas); 9 poltronas em branco (disponíveis), espalhadas pelas fileiras.")), ["arranjo"],
  alts={"A": K("\\dfrac{9!}{2!}"), "B": K("\\dfrac{9!}{7! \\times 2!}"), "C": "7!", "D": K("\\dfrac{5!}{2!} \\times 4!"), "E": K("\\dfrac{5!}{4!} \\times \\dfrac{4!}{3!}")})
X(165, "Geometria plana", "<p>A piscina tem 3 setores de 60° e raio R: área 3 · (πR²/6) = πR²/2 = 1,5R². Ela deve ser menor que a retangular, 50 × 24 = 1 200 m²: 1,5R² &lt; 1 200, R² &lt; 800, R &lt; 28,3. O maior natural é <strong>28</strong>. Alternativa <strong>B</strong>.</p>",
  p("O proprietário de um parque aquático deseja construir uma piscina em suas dependências. A figura representa a vista superior dessa piscina, que é formada por três setores circulares idênticos, com ângulo central igual a 60°. O raio <em>R</em> deve ser um número natural.") + "[[fig:1]]"
  + p("O parque aquático já conta com uma piscina em formato retangular com dimensões 50 m x 24 m.", "O proprietário quer que a área ocupada pela nova piscina seja menor que a ocupada pela piscina já existente.", "Considere 3,0 como aproximação para π.", "O maior valor possível para <em>R</em>, em metros, deverá ser"),
  figs(("q165", "Vista superior da piscina: três setores circulares de raio R e ângulo de 60°, encaixados lado a lado, formando uma figura em leque.")), ["setor circular"])
X(166, "Operações e problemas", "<p>Em 10 horas, um copo a cada meia hora são 20 copos de 150 mL: 3 000 mL = 3 L. Em duas garrafas iguais: 1,5 L cada, a garrafa <strong>IV</strong>. Alternativa <strong>D</strong>.</p><p>Duas garrafas V (E) dariam 6 L, o dobro do recomendado.</p>",
  p(T(166, 0)) + ap("• Garrafa I: 0,15 litro<br>• Garrafa II: 0,30 litro<br>• Garrafa III: 0,75 litro<br>• Garrafa IV: 1,50 litro<br>• Garrafa V: 3,00 litros") + p(T(166, 2), T(166, 3)), tags=["unidades de medida"])
X(167, "Geometria plana", "<p>A folha dobrada ao meio tem quatro camadas; o corte de M a N e de N a O (passando pelo ponto N, no meio da base) tira um triângulo da borda inferior. Ao abrir, esse corte aparece repetido de forma simétrica: a bandeirinha fica com duas pontas laterais e um entalhe em “V” no meio, alto e estreito, como na figura E. Alternativa <strong>E</strong>.</p><p>Dica: reproduza com uma folha de papel; o recorte mais confiável para esse tipo de questão é o de mão.</p>",
  p(T(167, 0)) + "[[fig:1]]" + p("Após os cortes, a folha é aberta e a bandeirinha está pronta.", "A figura que representa a forma da bandeirinha pronta é"),
  figs(("q167", "Figura 1: quadrado ABCD. Figura 2: a folha dobrada, um retângulo com vértices A, F, G e D; M no lado AD, a um quarto de AD a partir de A; N no ponto médio de AF; O no ponto médio de FG; linhas tracejadas de M a N e de N a O."),
       ("q167a", "Alternativa A: bandeirinha com um entalhe em V largo e fundo na parte de baixo."), ("q167b", "Alternativa B: bandeirinha com um entalhe em V pequeno no meio da parte de baixo."),
       ("q167c", "Alternativa C: bandeirinha com um entalhe em V deslocado para a esquerda."), ("q167d", "Alternativa D: bandeirinha sem entalhe, com a parte de baixo em ponta."),
       ("q167e", "Alternativa E: bandeirinha com um entalhe em V alto e estreito no meio da parte de baixo.")), ["simetria", "dobradura"],
  alts={k: f"[[fig:{i}]]" for i, k in enumerate("ABCDE", 2)})
X(168, "Probabilidade", "<p>É mais fácil calcular o contrário: nenhum dos três entende, com probabilidade 0,7³ = 0,343. Então a chance de pelo menos um entender é 1 − 0,343 = 0,657 = <strong>65,7%</strong>. Alternativa <strong>D</strong>.</p><p>Somar 30% três vezes daria 90% (E), contando duas vezes os casos em que mais de um entende.</p>",
  p(T(168, 0), T(168, 1)), tags=["evento complementar"])
X(169, "Estatística", "<p>Os usos têxteis são 37,8% de 282 kton ≈ 106,6 kton. Desses, tecidos e malhas são 30%: 0,3 × 106,6 ≈ <strong>32,0 kton</strong>. Alternativa <strong>C</strong>.</p><p>106,6 (E) é o total têxtil; 84,6 (D) é 30% de 282, pulando a primeira porcentagem.</p>",
  p(T(169, 0)) + "[[fig:1]]" + '<p class="fonte">Disponível em: www.abipet.org.br. Acesso em: 12 jul. 2012 (adaptado).</p>' + p("De acordo com os gráficos, a quantidade de embalagens PET recicladas destinadas à produção de tecidos e malhas, em kton, é mais aproximadamente de"),
  figs(("q169", "Dois gráficos de setores “PET reciclado – 2010”. Usos finais: têxteis 37,8%; resinas insaturadas e alquídicas 18,9%; embalagens de alimentos e não alimentos 17,2%; laminados e chapas 7,9%; outros 7,6%; fitas de arquear 6,8%; tubos 3,8%. Usos finais têxteis: não tecidos 43%; tecidos e malhas 30%; cordas, cordões e monofilamentos 27%.")), ["porcentagem", "leitura de gráfico"])
X(170, "Estatística", "<p>Médias finais: A = (4 · 90 + 60) ÷ 5 = 84; B = (340 + 85) ÷ 5 = 85; C = (320 + 95) ÷ 5 = 83; D = (240 + 90) ÷ 5 = 66; E = (240 + 100) ÷ 5 = 68. Ordem: B, A, C, E, D. Alternativa <strong>B</strong>.</p><p>Somar a média das quatro com a quinta, sem pesos, leva a outras ordens (A, C e D).</p>",
  p("Um concurso é composto por cinco etapas. Cada etapa vale 100 pontos. A pontuação final de cada candidato é a média de suas notas nas cinco etapas. A classificação obedece à ordem decrescente das pontuações finais. O critério de desempate baseia-se na maior pontuação na quinta etapa.")
  + tab(["Candidato", "Média nas quatro primeiras etapas", "Pontuação na quinta etapa"], [["A", "90", "60"], ["B", "85", "85"], ["C", "80", "95"], ["D", "60", "90"], ["E", "60", "100"]]) + p("A ordem de classificação final desse concurso é"), tags=["média ponderada"])
X(171, "Geometria espacial", "<p>A água acumulada na lata foi 1/3 do volume: (1/3) · 3 · 0,3² · 1,2 = 0,108 m³. O índice é a altura que essa água teria num tanque de base 1 m²: 0,108 m³ ÷ 1 m² = 0,108 m = <strong>108 mm</strong>. Alternativa <strong>D</strong>.</p><p>Esquecer o terço dá 324 mm (E); usar a altura da água dentro da lata (400 mm) não segue a definição do índice.</p>",
  p(T(171, 0).replace("1 m2", "1 m<sup>2</sup>").replace("1 m²", "1 m<sup>2</sup>"), T(171, 1), T(171, 2)), tags=["cilindro", "volume"])
X(172, "Geometria analítica", "<p>O ônibus vai de P(30, 20) pela Rua A até (550, 20) e sobe pela Rua B até Q(550, 320): percurso de 520 + 300 = 820. O ponto T fica no meio do percurso, a 410 de P pela Rua A: x = 30 + 410 = 440 e y = 20. T = <strong>(440 ; 20)</strong>. Alternativa <strong>E</strong>.</p><p>(290 ; 20) é o meio só da Rua A (A); (440 ; 0) erra a ordenada (D).</p>",
  p(T(172, 0)) + "[[fig:1]]" + p(*[x for t, x in D[172]["paragrafos"][1:] if t == "p"][-2:]),
  figs(("q172", "Plano cartesiano com o mapa: Rua A horizontal em y = 20, de x = 30 (ponto P) a x = 550; Rua B vertical em x = 550, de y = 20 a y = 320 (ponto Q); Rua C horizontal em y = 320. Setas mostram o ônibus indo de P pela Rua A e subindo pela Rua B até Q.")), ["distância", "percurso"])
X(173, "Operações e problemas", "<p>Distâncias até 3 mm: 3,10 (0,10); 3,021 (0,021); 2,96 (0,04); 2,099 (0,901); 3,07 (0,07). A mais próxima é <strong>3,021 mm</strong>. Alternativa <strong>C</strong>.</p><p>O erro comum é achar que 3,07 ou 3,10 estão mais perto por “começarem com 3,0”.</p>",
  p("Deseja-se comprar lentes para óculos. As lentes devem ter espessuras mais próximas possíveis da medida 3 mm. No estoque de uma loja, há lentes de espessuras: 3,10 mm; 3,021 mm; 2,96 mm; 2,099 mm e 3,07 mm.", "Se as lentes forem adquiridas nessa loja, a espessura escolhida será, em milímetros, de"), tags=["números decimais"])
X(174, "Funções", "<p>T(h) = −h² + 22h − 85 é uma parábola com máximo no vértice: h = −22/(2 · −1) = 11. T(11) = −121 + 242 − 85 = 36 °C, que está entre 30 e 43: <strong>alta</strong>. Alternativa <strong>D</strong>.</p>",
  p("Um estudante está pesquisando o desenvolvimento de certo tipo de bactéria. Para essa pesquisa, ele utiliza uma estufa para armazenar as bactérias. A temperatura no interior dessa estufa, em graus Celsius, é dada pela expressão \\(T(h) = -h^2 + 22h - 85\\), em que <em>h</em> representa as horas do dia. Sabe-se que o número de bactérias é o maior possível quando a estufa atinge sua temperatura máxima e, nesse momento, ele deve retirá-las da estufa. A tabela associa intervalos de temperatura, em graus Celsius, com as classificações: muito baixa, baixa, média, alta e muito alta.")
  + tab(["Intervalos de temperatura (°C)", "Classificação"], [["<em>T</em> &lt; 0", "Muito baixa"], ["0 ≤ <em>T</em> ≤ 17", "Baixa"], ["17 &lt; <em>T</em> &lt; 30", "Média"], ["30 ≤ <em>T</em> ≤ 43", "Alta"], ["<em>T</em> &gt; 43", "Muito alta"]])
  + p("Quando o estudante obtém o maior número possível de bactérias, a temperatura no interior da estufa está classificada como"), tags=["função quadrática", "vértice"])
X(175, "Geometria espacial", "<p>O comprimento horizontal é 2a e o vertical, 2b. A diferença é a metade do vertical: 2a − 2b = b, logo a = 3b/2. Volume: V = 4ab² = 4 · (3b/2) · b² = <strong>6b³</strong>. Alternativa <strong>B</strong>.</p>",
  p("A figura representa a vista superior de uma bola de futebol americano, cuja forma é um elipsoide obtido pela rotação de uma elipse em torno do eixo das abscissas. Os valores <em>a</em> e <em>b</em> são, respectivamente, a metade do seu comprimento horizontal e a metade do seu comprimento vertical. Para essa bola, a diferença entre os comprimentos horizontal e vertical é igual à metade do comprimento vertical.") + "[[fig:1]]"
  + p("Considere que o volume aproximado dessa bola é dado por \\(V = 4ab^2\\).", "O volume dessa bola, em função apenas de <em>b</em>, é dado por"),
  figs(("q175", "Bola de futebol americano vista de cima, em forma de elipse centrada na origem, com vértices em (−a, 0), (a, 0), (0, b) e (0, −b).")), ["elipse", "volume"],
  alts={k: f"{c}<em>b</em><sup>3</sup>" for k, c in zip("ABCDE", [8, 6, 5, 4, 2])})
X(176, "Funções", "<p>Até 100 ligações paga-se só o fixo de R$ 12,00 (trecho horizontal). Da 101ª à 300ª, mais R$ 0,10 por ligação: 200 × 0,10 = R$ 20,00, chegando a R$ 32,00 (trecho crescente). De 300 a 500, valor fixo de R$ 32,00 (trecho horizontal). É o gráfico B. Alternativa <strong>B</strong>.</p><p>C continua subindo depois de 300; A e E começam em zero; D começa subindo.</p>",
  p(T(176, 0).replace("101ª", "101<sup>a</sup>").replace("300ª", "300<sup>a</sup>").split(" Com base")[0], "Com base nos elementos apresentados, o gráfico que melhor representa a relação entre o valor mensal pago nesse plano e o número de ligações feitas é:"),
  figs(("q176a", "Gráfico A: reta crescente da origem até R$ 32 em 300 ligações, depois constante."), ("q176b", "Gráfico B: constante em R$ 12 até 100 ligações, cresce até R$ 32 em 300 ligações e fica constante até 400."),
       ("q176c", "Gráfico C: constante em R$ 12 até 100 ligações, cresce até R$ 32 em 300 e continua subindo devagar."), ("q176d", "Gráfico D: começa em R$ 12, cresce até R$ 30 em 300 ligações e salta para R$ 32, constante."),
       ("q176e", "Gráfico E: cresce da origem até cerca de R$ 32 em 300 ligações e continua subindo devagar.")), ["função definida por partes"],
  alts={k: f"[[fig:{i}]]" for i, k in enumerate("ABCDE", 1)})
X(177, "Razão e proporção", "<p>Pela tabela, um felino de 3,0 kg tem 0,208 m² de superfície corporal. Dose: 250 mg/m² × 0,208 m² = <strong>52,0 mg</strong>. Alternativa <strong>B</strong>.</p><p>Multiplicar a dose pela massa daria 750 mg (D).</p>",
  p("Alguns medicamentos para felinos são administrados com base na superfície corporal do animal. Foi receitado a um felino pesando 3,0 kg um medicamento na dosagem diária de 250 mg por metro quadrado de superfície corporal.", "O quadro apresenta a relação entre a massa do felino, em quilogramas, e a área de sua superfície corporal, em metros quadrados.")
  + p("<strong>Relação entre a massa de um felino e a área de sua superfície corporal</strong>") + tab(["Massa (kg)", "Área (m<sup>2</sup>)"], [["1,0", "0,100"], ["2,0", "0,159"], ["3,0", "0,208"], ["4,0", "0,252"], ["5,0", "0,292"]])
  + '<p class="fonte">NORSWORTHY, G. D. <strong>O paciente felino</strong>. São Paulo: Roca, 2009.</p>' + p("A dose diária, em miligramas, que esse felino deverá receber é de"), tags=["leitura de tabela"])
X(178, "Operações e problemas", "<p>Consumo: 10 pessoas × 0,08 m³ × 20 dias = 16 m³ = <strong>16 000 L</strong> (1 m³ = 1 000 L). Alternativa <strong>E</strong>.</p><p>16 (A) é o valor em m³, sem converter.</p>",
  p("Para economizar em suas contas mensais de água, uma família de 10 pessoas deseja construir um reservatório para armazenar a água captada das chuvas, que tenha capacidade suficiente para abastecer a família por 20 dias. Cada pessoa da família consome, diariamente, 0,08 m<sup>3</sup> de água.", "Para que os objetivos da família sejam atingidos, a capacidade mínima, em litros, do reservatório a ser construído deve ser"), tags=["unidades de medida"])
X(179, "Probabilidade", "<p>Modo I: 3 atletas entre 200: P = 3/200. Modo II: a equipe dele é sorteada (1/20) e ele está entre os 3 de 10 (3/10): 3/200. Modo III: a equipe dele está entre as 3 sorteadas (3/20) e ele é o escolhido dela (1/10): 3/200. As três são iguais. Alternativa <strong>E</strong>.</p>",
  p(T(179, 0).replace("antidoping", "<em>antidoping</em>")) + ap(*[T(179, i).replace("Modo I", "<strong>Modo I").replace(":", ":</strong>", 1) for i in (1, 2, 3)]) + p(T(179, 4).replace("P(I)", "<em>P</em>(I)").replace("P(II)", "<em>P</em>(II)").replace("P(III)", "<em>P</em>(III)"), T(179, 5)),
  tags=["probabilidade"], alts={k: v.replace("P(", "<em>P</em>(") for k, v in D[179]["alternativas"].items()})
X(180, "Trigonometria", "<p>Na produção máxima o produto é abundante e o preço é <strong>mínimo</strong>. P(x) = 8 + 5 cos((πx − π)/6) é mínimo quando o cosseno vale −1: (πx − π)/6 = π, logo x − 1 = 6 e x = 7, <strong>julho</strong>. Alternativa <strong>D</strong>.</p><p>Quem procura o preço máximo chega a janeiro (A).</p>",
  p(T(180, 0)) + p("A partir de uma série histórica, observou-se que o preço <em>P</em>, em reais, do quilograma de um certo produto sazonal pode ser descrito pela função \\(P(x) = 8 + 5\\cos\\left(\\dfrac{\\pi x - \\pi}{6}\\right)\\), onde <em>x</em> representa o mês do ano, sendo <em>x</em> = 1 associado ao mês de janeiro, <em>x</em> = 2 ao mês de fevereiro, e assim sucessivamente, até <em>x</em> = 12 associado ao mês de dezembro.") + fonte(180, 5) + p(T(180, 6)),
  tags=["função cosseno"])

completar(Q, R)
